import java.text.SimpleDateFormat
import java.util.Date
import java.security.MessageDigest
import java.math.BigInteger

try {
    // ========== 1. DATA CLEANING ==========

    // Trim all string fields
    def textFields = ['event_id', 'airline', 'flight_number', 'aircraft_model', 'aircraft_type',
                     'origin', 'destination', 'city', 'country', 'cause', 'damage']

    textFields.each { fieldName ->
        def value = record.getValue(fieldName)
        if (value != null) {
            record.setValue(fieldName, value.toString().trim())
        }
    }

    // Damage field - uppercase
    def damage = record.getValue('damage')
    if (damage != null) {
        record.setValue('damage', damage.toString().toUpperCase())
    }

    // Flight number - standardize format
    def flightNum = record.getValue('flight_number')
    if (flightNum != null) {
        def cleanFlight = flightNum.toString().toUpperCase()
        cleanFlight = cleanFlight.replaceAll('[^A-Z0-9\\-]', '')
        record.setValue('flight_number', cleanFlight)
    }

    // ========== 2. DUPLICATE DETECTION HASH ==========
    def eventId = record.getValue('event_id')
    if (eventId != null) {
        // Create a hash of key fields for duplicate detection
        def duplicateKey = [
            eventId.toString(),
            record.getValue('flight_number') ?: '',
            record.getValue('timestamp') ?: ''
        ].collect { it.toString() }.join('|')

        // Create MD5 hash
        def md5 = MessageDigest.getInstance("MD5")
        md5.update(duplicateKey.getBytes())
        def hash = new BigInteger(1, md5.digest()).toString(16).padLeft(32, '0')
        record.setValue('_record_hash', hash)
    }

    // ========== 3. DATA TYPE CONVERSION ==========

    // Numeric fields
    ['fatalities', 'injuries'].each { fieldName ->
        def value = record.getValue(fieldName)
        if (value != null) {
            try {
                def num = Integer.parseInt(value.toString().trim())
                record.setValue(fieldName, num)
            } catch (Exception e) {
                record.setValue(fieldName, 0)
            }
        } else {
            record.setValue(fieldName, 0)
        }
    }

    // Coordinate fields
    ['latitude', 'longitude'].each { fieldName ->
        def value = record.getValue(fieldName)
        if (value != null) {
            try {
                def coord = Double.parseDouble(value.toString().trim())
                record.setValue(fieldName, coord)
            } catch (Exception e) {
                // Keep original as string
            }
        }
    }

    // Timestamp processing
    def timestamp = record.getValue('timestamp')
    if (timestamp != null) {
        try {
            def tsLong = Long.parseLong(timestamp.toString().trim())

            // Create date object
            def date = new Date(tsLong)

            // Add date components
            record.setValue('year', date.getYear() + 1900)
            record.setValue('month', date.getMonth() + 1)
            record.setValue('day', date.getDate())
            record.setValue('hour', date.getHours())

            // Day of week
            def days = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday']
            record.setValue('day_of_week', days[date.getDay()])

        } catch (Exception e) {
            // Keep original timestamp
        }
    }

    // ========== 4. ENCODING CATEGORICAL DATA ==========

    // Damage encoding
    def damageValue = record.getValue('damage')
    if (damageValue != null) {
        def damageStr = damageValue.toString().toUpperCase()
        def damageCode = 'UNKNOWN'

        if (damageStr.contains('DESTROYED') || damageStr.contains('TOTAL')) {
            damageCode = 'DESTROYED'
        } else if (damageStr.contains('SUBSTANTIAL') || damageStr.contains('MAJOR')) {
            damageCode = 'MAJOR'
        } else if (damageStr.contains('MINOR') || damageStr.contains('SLIGHT')) {
            damageCode = 'MINOR'
        } else if (damageStr.contains('NONE') || damageStr == '0') {
            damageCode = 'NONE'
        }
        record.setValue('damage_code', damageCode)

        // Numeric severity score
        def damageScore = -1
        switch(damageCode) {
            case 'DESTROYED':
                damageScore = 3
                break
            case 'MAJOR':
                damageScore = 2
                break
            case 'MINOR':
                damageScore = 1
                break
            case 'NONE':
                damageScore = 0
                break
        }
        record.setValue('damage_severity_score', damageScore)
    }

    // Region encoding
    def country = record.getValue('country')
    if (country != null) {
        def countryStr = country.toString().toUpperCase()
        def region = 'OTHER'

        if (countryStr.contains('USA') || countryStr.contains('UNITED STATES') || 
            countryStr.contains('CANADA') || countryStr.contains('MEXICO')) {
            region = 'NORTH_AMERICA'
        } else if (countryStr.contains('UK') || countryStr.contains('UNITED KINGDOM') || 
                  countryStr.contains('GERMANY') || countryStr.contains('FRANCE')) {
            region = 'EUROPE'
        } else if (countryStr.contains('CHINA') || countryStr.contains('JAPAN') || 
                  countryStr.contains('INDIA')) {
            region = 'ASIA'
        } else if (countryStr.contains('BRAZIL') || countryStr.contains('ARGENTINA')) {
            region = 'SOUTH_AMERICA'
        }
        record.setValue('region', region)
    }

    // ========== 5. VALIDATION ==========

    def isValid = true
    def validationErrors = []

    // Required fields
    if (!record.getValue('event_id') || record.getValue('event_id').toString().isEmpty()) {
        validationErrors.add("MISSING_EVENT_ID")
        isValid = false
    }

    // Add validation status
    if (isValid) {
        record.setValue('validation_status', 'VALID')
    } else {
        record.setValue('validation_status', 'INVALID: ' + validationErrors.join(', '))
    }
    record.setValue('is_valid', isValid)

    // ========== 6. CREATE NEW COLUMNS ==========

    // Accident category
    def cause = record.getValue('cause')
    if (cause != null) {
        def causeStr = cause.toString().toUpperCase()
        def accidentCategory = 'OTHER'

        if (causeStr.contains('WEATHER')) {
            accidentCategory = 'WEATHER_RELATED'
        } else if (causeStr.contains('MECHANICAL') || causeStr.contains('ENGINE')) {
            accidentCategory = 'MECHANICAL_FAILURE'
        } else if (causeStr.contains('HUMAN') || causeStr.contains('PILOT')) {
            accidentCategory = 'HUMAN_ERROR'
        }
        record.setValue('accident_category', accidentCategory)
    }

    // Safety score (simplified)
    def safetyScore = 100
    def fatalityCount = record.getValue('fatalities')
    if (fatalityCount instanceof Integer && fatalityCount > 0) {
        safetyScore -= Math.min(50, fatalityCount * 10)
    }

    def damageSeverity = record.getValue('damage_severity_score')
    if (damageSeverity instanceof Integer && damageSeverity > 0) {
        safetyScore -= damageSeverity * 15
    }

    safetyScore = Math.max(0, Math.min(100, safetyScore))
    record.setValue('safety_score', safetyScore)

    // Risk level
    def riskLevel = 'LOW'
    if (safetyScore < 30) {
        riskLevel = 'CRITICAL'
    } else if (safetyScore < 50) {
        riskLevel = 'HIGH'
    } else if (safetyScore < 70) {
        riskLevel = 'MEDIUM'
    }
    record.setValue('risk_level', riskLevel)

    // Casualties flag
    def fatalities = record.getValue('fatalities')
    def injuries = record.getValue('injuries')
    def hasCasualties = 'NO'

    try {
        def fatalityCountInt = fatalities instanceof Integer ? fatalities : 0
        def injuryCountInt = injuries instanceof Integer ? injuries : 0
        if (fatalityCountInt > 0 || injuryCountInt > 0) {
            hasCasualties = 'YES'
        }
    } catch (Exception e) {
        // Ignore
    }
    record.setValue('has_casualties', hasCasualties)

    // ========== 7. METADATA ==========

    record.setValue('_processed_timestamp', System.currentTimeMillis())
    record.setValue('_pipeline_stage', 'NiFi_Transformation_v1')

    // Return the transformed record
    return record

} catch (Exception e) {
    log.error("Transformation failed: " + e.getMessage(), e)

    // Add error info but still return record
    record.setValue('_transformation_error', e.getMessage())
    record.setValue('_transformation_status', 'FAILED')

    return record
}
